/* Browns season hub: no account needed to explore; GitHub submissions are explicit. */
(()=>{'use strict';
const H=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),now=()=>Date.now();
const titleMap={hq:['DAWG POUND / GAME DAY','Browns HQ','The next game. The playoff race. Your next move.'],road:['EVERY RESULT HAS A CONSEQUENCE','Road to January','Choose Cleveland’s final record. Explore the odds and build a path.'],pickem:['THE DAWG POUND PICKS','Fan Pick’em','Pick the weekly slate. Bring your friends. Settle it on the leaderboard.'],confidence:['TAKE THE TEMPERATURE','Confidence meter','How are you feeling about the Browns? Put a number on it.'],matchup:['THE NEXT CHALLENGE','Matchup lab','Compare scoring, form and opponent-adjusted strength before kickoff.'],receipts:['KEEP THAT SAME ENERGY','Receipt tracker','Make the call before kickoff. Keep the timestamp. Let the results speak.'],graphics:['MAKE SOME NOISE','Graphic factory','Turn your prediction, matchup or playoff scenario into a shareable Browns card.'],awards:['GIVE THE DAWGS THEIR FLOWERS','Season awards','Choose the MVP, best play, biggest surprise and unsung hero.']};
let view='simulator',community={entries:[],updated:null},communityError=false,roster={players:[]},live={},liveWeek=null,liveAt=null,liveError='',autoLive=false,hqWeek=null,roadWins=null,hubWorker=null,hqResult=null,hqVersion=-1,currentDraft=null,scoreView='upcoming';
let pickDraft=read('temu-pickem-draft',{week:null,league:'dawg-pound',picks:{}}),receiptDraft=read('temu-receipt-draft',{game:'',winner:1,note:''}),localReceipts=read('temu-local-receipts',[]),graphicState={type:'prediction',away:20,home:24,caption:'THE DAWG POUND BELIEVES',game:''},pollState={topic:'next-game',value:7,week:null},awardState={category:'mvp',period:'season',week:null,nominee:''};
function read(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Device storage is unavailable. You can still submit publicly.')}}
const logo=t=>`<span class="team-logo" style="--team:${meta[t][1]}">${t}</span>`;
const fmtDate=g=>g.timeTBD?'Week '+g.week+' · Kickoff TBD':new Date(g.date).toLocaleString('en-US',{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'});
const cleGames=()=>data.games.filter(g=>[g.h,g.a].includes('CLE')).sort((a,b)=>new Date(a.date)-new Date(b.date));
const nextGame=()=>cleGames().find(g=>!g.done)||cleGames().at(-1);
const opponent=g=>g.h==='CLE'?g.a:g.h;
const currentWeek=()=>Math.min(...data.games.filter(g=>!g.done).map(g=>g.week),18);
const allWeeks=()=>[...new Set(data.games.map(g=>g.week))].sort((a,b)=>a-b);
const outcome=g=>g.hs===g.as_?.5:g.hs>g.as_?1:0;
const cleWin=g=>outcome(g)===(g.h==='CLE'?1:0);
const valueLabel=(g,v)=>v===.5?'Tie':short(v===1?g.h:g.a)+' win';
function stats(t){let gs=data.games.filter(g=>g.done&&[g.h,g.a].includes(t));let pf=0,pa=0;gs.forEach(g=>{pf+=g.h===t?g.hs:g.as_;pa+=g.h===t?g.as_:g.hs});return {games:gs.length,pf:gs.length?pf/gs.length:0,pa:gs.length?pa/gs.length:0,net:gs.length?(pf-pa)/gs.length:0,form:gs.sort((a,b)=>new Date(a.date)-new Date(b.date)).slice(-5).map(g=>outcome(g)===.5?'T':(outcome(g)===(g.h===t?1:0)?'W':'L'))}}
function header(key,actions=''){let t=titleMap[key];return `<div class="hub-title"><div><span class="hub-tag">${t[0]}</span><h1 tabindex="-1">${t[1]}</h1><p>${t[2]}</p></div><div class="hub-actions">${actions}</div></div>`}
function notice(){return `<div class="hub-notice"><span class="notice-icon" data-icon="info" aria-hidden="true"></span><div class="notice-copy"><div class="notice-main"><strong>A free GitHub account is needed to submit.</strong><span>Your username and entry will be public.</span></div><details><summary>How community entries work</summary><p>Review your entry here, then finish submitting on GitHub. Accepted entries appear after validation and publication, usually within a few minutes. Exploring the tools and saving personal drafts needs no account. Nothing is posted automatically.</p></details></div></div>`}
function communityState(){return `<div class="community-state"><span>${communityError?'Community results unavailable. Try refreshing.':community.updated?'Community snapshot · '+esc(new Date(community.updated).toLocaleString()):'No community entries yet. Be the first.'}</span><button data-community-refresh>Refresh community</button></div>`}
function route(key,update=true){if(key!=='simulator'&&!titleMap[key])key='hq';let changed=view!==key;view=key;H('simulatorView').hidden=view!=='simulator';H('hubView').hidden=view==='simulator';document.body.classList.toggle('hub-mode',view!=='simulator');document.body.dataset.currentView=view;document.querySelectorAll('[data-hub]').forEach(b=>b.classList.toggle('active',b.dataset.hub===view));if(update&&changed){let u=new URL(location.href);u.searchParams.set('tab',view);history.pushState({view},'',u.href)}render();document.dispatchEvent(new CustomEvent('lab:route',{detail:{view}}));if(update&&changed){window.scrollTo({top:0,behavior:'auto'});requestAnimationFrame(()=>{let heading=document.querySelector(view==='simulator'?'#simulatorView h1':'#hubView h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}})}}
function render(){if(view==='simulator')return;if(!data){H('hubView').innerHTML=dataError?'<div class="hub-loader"><h1>Let’s try that again.</h1><p>The season data couldn’t load. Your saved picks are still on this device.</p><button id="retryHubData" class="hub-primary">Retry loading data</button></div>':'<div class="hub-loader">Getting your Browns season ready…</div>';if(H('retryHubData'))H('retryHubData').onclick=()=>load();return}let active=document.activeElement,activeId=H('hubView').contains(active)?active.id:null,pickFocus=active?.dataset?.pickem?{id:active.dataset.pickem,value:active.dataset.v}:null;let fn={hq:renderHQ,road:renderRoad,pickem:renderPickem,confidence:renderConfidence,matchup:renderMatchup,receipts:renderReceipts,graphics:renderGraphics,awards:renderAwards}[view];H('hubView').innerHTML=fn();bindCommon();({hq:bindHQ,road:bindRoad,pickem:bindPickem,confidence:bindConfidence,matchup:bindMatchup,receipts:bindReceipts,graphics:bindGraphics,awards:bindAwards}[view])();document.dispatchEvent(new Event('lab:hubrender'));if(activeId)H(activeId)?.focus({preventScroll:true});else if(pickFocus)[...H('hubView').querySelectorAll('[data-pickem]')].find(b=>b.dataset.pickem===pickFocus.id&&b.dataset.v===pickFocus.value)?.focus({preventScroll:true})}
function bindCommon(){H('hubView').querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>route(b.dataset.route));H('hubView').querySelectorAll('[data-community-refresh]').forEach(b=>b.onclick=async()=>{await loadCommunity();render()})}
function weekOptions(selected,weeks=allWeeks()){return weeks.map(w=>`<option value="${w}" ${+selected===w?'selected':''}>Week ${w}</option>`).join('')}
function getBrowns(){return output?.result.CLE}
function needHQ(){if(!output)return;if(output.focus==='CLE'){hqResult=output;hqVersion=version;return}if(hqVersion===version)return;hqVersion=version;hqResult=null;hubWorker?.terminate();let v=version;hubWorker=new Worker('engine.js?v=4');hubWorker.onmessage=e=>{if(v!==version)return;hqResult=e.data;if(view==='hq')render()};hubWorker.postMessage({data,picks,N:10000,focus:'CLE',version:v})}
function guide(){let source=output?.focus==='CLE'?output:hqResult;if(!source)return [];return data.games.filter(g=>!g.done&&g.week===+hqWeek).map(g=>{let locked=picks[g.id]!==undefined;let src=locked?(baselineCache.CLE):source;let i=src?.impact[g.id];if(!i||i.counts[0]<100||i.counts[2]<100)return null;let a=i.qualified[0]/i.counts[0],h=i.qualified[2]/i.counts[2],se=Math.sqrt(a*(1-a)/i.counts[0]+h*(1-h)/i.counts[2]);return {g,help:h>a?g.h:g.a,swing:100*Math.abs(h-a),win:100*Math.max(h,a),lose:100*Math.min(h,a),reliable:Math.abs(h-a)>1.96*se,locked}}).filter(Boolean).sort((a,b)=>b.swing-a.swing)}
function homeOdds(){if(!output||!baseline)return '<p class="hub-loader">Calculating team playoff odds…</p>';return `<section class="home-odds hub-card"><div class="hub-stats-head"><div><span class="hub-tag">PLAYOFF PICTURE</span><h2>Every team. One glance.</h2></div><button data-route="simulator">Make your picks →</button></div><p>Current = no picks. Your picks = your scenario. Model estimates from the published snapshot.</p><div class="home-conferences">${['AFC','NFC'].map(c=>`<div><h3>${c}</h3><div class="home-odds-head"><span>Team</span><span>Current</span><span>Your picks</span></div>${Object.keys(meta).filter(t=>afc.includes(t)===(c==='AFC')).sort((a,b)=>baseline.result[b].play-baseline.result[a].play).map(t=>`<div class="home-odds-row ${t==='CLE'?'cle-row':''}"><span>${logo(t)}<strong>${short(t)}</strong></span><b>${percent(baseline.result[t].play)}</b><b>${percent(output.result[t].play)}</b></div>`).join('')}</div>`).join('')}</div></section>`}

function scoreTile(g){let l=liveWeek===+hqWeek?live[g.id]:null;let done=l?l.done:g.done,inProgress=l?.state==='in',status=l?.status||(g.done?'FINAL':fmtDate(g));return `<div class="score-tile ${inProgress?'live':''}"><div class="status-line"><span>${esc(status)}</span><span>${l?'ESPN':'SNAPSHOT'}</span></div><div class="score-team">${logo(g.a)}<span>${short(g.a)}</span><b>${done||inProgress?l?l.as_:g.as_:'—'}</b></div><div class="score-team">${logo(g.h)}<span>${short(g.h)}</span><b>${done||inProgress?l?l.hs:g.hs:'—'}</b></div><a class="score-link" target="_blank" rel="noopener" href="https://www.espn.com/nfl/game/_/gameId/${g.id}">Game details ↗</a></div>`}
function renderHQ(){hqWeek??=currentWeek();needHQ();let g=nextGame(),r=getBrowns(),tips=guide(),sg=data.games.filter(g=>g.week===+hqWeek&&(afc.includes(g.h)||afc.includes(g.a))).sort((a,b)=>new Date(a.date)-new Date(b.date));let shown=scoreView==='upcoming'?sg.filter(g=>!g.done):sg;let futureWeek=[...new Set(data.games.filter(x=>!x.done&&x.week>+hqWeek).map(x=>x.week))].sort((a,b)=>a-b)[0];let sharePicks=Object.keys(picks).length;const side=t=>`<div class="hq-club">${logo(t)}<div><strong>${short(t)}</strong><small>${record(t)} record</small></div></div>`;let fresh=new Date(data.updated).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});return header('hq')+`<div class="hq-overview"><section class="hq-matchup"><div class="hq-matchup-top"><span>${g.done?'LAST BROWNS GAME':'NEXT BROWNS GAME'}</span><span class="hub-badge">WEEK ${g.week}</span></div><h2>Cleveland ${g.h==='CLE'?'vs.':'at'} ${short(opponent(g))}</h2><p class="match-date">${fmtDate(g)}${g.neutral?' · Neutral site':''}</p><div class="hq-matchup-teams">${side(g.a)}<span class="hq-versus">${g.neutral?'VS':'AT'}</span>${side(g.h)}</div><div class="hq-matchup-footer"><span>${g.done?'FINAL · '+g.a+' '+g.as_+' — '+g.hs+' '+g.h:'Browns model win chance: '+Math.round((g.h==='CLE'?g.p:1-g.p)*100)+'%'}</span><button data-route="matchup">Matchup preview <span data-icon="arrow" aria-hidden="true"></span></button></div></section><section class="hq-chances"><span class="eyebrow">THE ROAD TO JANUARY</span><h2>Cleveland’s playoff chances</h2><div class="hq-chance-number">${r?percent(r.play):'—'}</div><div class="hq-chance-track" aria-hidden="true"><i style="width:${r?100*r.play/N:0}%"></i></div><p class="chance-caption">${sharePicks?sharePicks+' of your game picks are included.':'Baseline model · no game picks yet.'}<br>Model snapshot: ${fresh}</p><div class="hq-chance-footer"><span>${r?(r.wins/N).toFixed(1):'—'} projected wins</span><button data-route="simulator">Change the picture <span data-icon="arrow" aria-hidden="true"></span></button></div></section></div>${homeOdds()}<div class="hq-quick-grid">${[['simulator','grid','Pick the games','See your choices change the odds'],['road','route','Find Cleveland’s path','Explore a final record'],['pickem','trophy','Make your weekly picks','Start a league with your people']].map(([key,icon,title,desc])=>`<button class="hq-quick" data-route="${key}"><span class="quick-icon" data-icon="${icon}" aria-hidden="true"></span><span><strong>${title}</strong><small>${desc}</small></span><span class="quick-arrow" data-icon="arrow" aria-hidden="true"></span></button>`).join('')}</div><div class="hub-grid"><section class="hub-card"><div class="hub-stats-head"><h2>Who to root for</h2><select id="hqWeek" aria-label="Command Center week">${weekOptions(hqWeek)}</select></div><p>Results that could help Cleveland reach the playoffs.</p>${tips.length?tips.map(({g,help,swing,win,lose,reliable,locked})=>`<div class="rooting-row">${logo(help)}<span>${reliable?'Root for':'Small estimated lean:'} <strong>${short(help)}</strong><small class="rooting-match">${g.a} at ${g.h}<br>Browns odds: ${win.toFixed(1)}% if ${short(help)} wins · ${lose.toFixed(1)}% if they lose${locked?'<br>Already picked · comparison uses baseline':''}${!reliable?'<br>Difference is within simulation noise':''}</small></span><b>${swing.toFixed(1)} pp swing</b><button data-help="${g.id}" data-v="${help===g.h?1:0}">Pick win</button></div>`).join(''):`<div class="hub-empty">${hqResult||output?.focus==='CLE'?'No clear playoff swings left in this week’s unpicked games.':'Working out Cleveland’s rooting guide…'}${futureWeek?`<br><button class="hq-empty-action" data-lookahead="${futureWeek}">Look ahead to Week ${futureWeek} <span data-icon="arrow" aria-hidden="true"></span></button>`:''}</div>`}<p class="tiny">Each matchup compares a win with a loss. Small leans are uncertain; they are not firm recommendations.</p></section><section class="hub-card"><div class="hub-stats-head"><h2>AFC scoreboard</h2><button id="liveRefresh" aria-label="Refresh live scores"><span data-icon="refresh" aria-hidden="true"></span> Refresh</button></div><div class="hub-score-controls"><div class="score-view-tabs" role="group" aria-label="Scoreboard games"><button data-score-view="upcoming" class="${scoreView==='upcoming'?'active':''}" aria-pressed="${scoreView==='upcoming'}">Upcoming</button><button data-score-view="all" class="${scoreView==='all'?'active':''}" aria-pressed="${scoreView==='all'}">All results</button></div><label class="hub-score-toggle"><input type="checkbox" id="autoLive" ${autoLive?'checked':''}>Auto refresh</label></div><div class="scoreboard-grid">${shown.length?shown.map(scoreTile).join(''):'<p class="hub-empty">No upcoming AFC games in this week. Choose All results to see the scores.</p>'}</div><p id="liveStatus" class="hub-score-note">${liveError?esc(liveError):liveAt&&liveWeek===+hqWeek?'Scores checked '+new Date(liveAt).toLocaleTimeString():'Published snapshot. Refresh for ESPN’s latest scores.'}</p><p class="hub-score-note">Live scores are separate from the playoff model snapshot. Auto refresh checks once a minute while this page is open.</p></section><section class="hub-card hub-card-wide hq-tools"><div class="hub-stats-head"><h2>Make it a Browns season.</h2><span class="hub-tag">MORE FROM THE DAWG POUND</span></div><div class="hub-grid three">${[['confidence','01','Take the temperature','Vote on the team, coaching and playoff hopes.'],['receipts','02','Keep the receipts','Put your next Browns call on the record.'],['graphics','03','Make something to share','Create a prediction, matchup or victory card.']].map(([key,num,title,desc])=>`<button class="hub-feature-link" data-route="${key}"><span class="feature-icon">${num}</span><span><b>${title}</b><small>${desc}</small></span><span data-icon="arrow" aria-hidden="true"></span></button>`).join('')}</div></section></div>`}
async function refreshScores(){if(!data)return;let w=+hqWeek;try{let res=await fetch(`https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard?dates=2026&seasontype=2&week=${w}&limit=1000`,{signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error();let d=await res.json(),map={};for(let e of d.events){let c=e.competitions[0],h=c.competitors.find(t=>t.homeAway==='home'),a=c.competitors.find(t=>t.homeAway==='away');map[e.id]={hs:+h.score,as_:+a.score,done:e.status.type.completed,state:e.status.type.state,status:e.status.type.shortDetail}}live=map;liveWeek=w;liveAt=now();liveError=''}catch{liveError='Score refresh unavailable. Showing the last successful feed or published snapshot.'}if(view==='hq')render()}
function bindHQ(){H('hqWeek').onchange=e=>{hqWeek=+e.target.value;render()};H('liveRefresh').onclick=async()=>{let b=H('liveRefresh');b.disabled=true;b.textContent='Checking…';await refreshScores()};H('autoLive').onchange=e=>autoLive=e.target.checked;H('hubView').querySelectorAll('[data-score-view]').forEach(b=>b.onclick=()=>{scoreView=b.dataset.scoreView;render()});H('hubView').querySelectorAll('[data-lookahead]').forEach(b=>b.onclick=()=>{hqWeek=+b.dataset.lookahead;render()});H('hubView').querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>{applyPicks({...picks,[b.dataset.help]:+b.dataset.v});toast('Result added to your playoff scenario')})}
function roadPlan(target){let gs=cleGames().filter(g=>!g.done),baseWins=output?.base.CLE.w??cleGames().filter(g=>g.done&&cleWin(g)).length;let sorted=gs.slice().sort((a,b)=>(b.h==='CLE'?b.p:1-b.p)-(a.h==='CLE'?a.p:1-a.p)),winIds=new Set(sorted.slice(0,Math.max(0,target-baseWins)).map(g=>g.id));return gs.map(g=>({g,win:winIds.has(g.id)}))}
function renderRoad(){let r=getBrowns(),base=output?.base.CLE,remaining=cleGames().filter(g=>!g.done).length,bw=base?.w??cleGames().filter(g=>g.done&&cleWin(g)).length;roadWins=Math.min(17,Math.max(bw,roadWins??Math.min(17,bw+Math.ceil(remaining*.65))));let samples=r?.noTieRecords?.[roadWins]||0,qual=r?.noTiePlayoffs?.[roadWins]||0,plan=roadPlan(roadWins);let max=Math.max(1,...(r?.noTieRecords||[1]));return header('road')+`<div class="hub-grid"><section class="hub-card"><span class="eyebrow">CHOOSE THE FINISH</span><h2>What if Cleveland finishes…</h2><div class="hub-form"><label>Final regular-season wins<select id="roadWins">${Array.from({length:remaining+1},(_,i)=>bw+i).map(w=>`<option ${w===roadWins?'selected':''} value="${w}">${w}–${17-w}</option>`).join('')}</select></label></div><div class="result-large">${samples>=100?percent(qual,samples):'—'}<small>Playoff chance conditional on ${roadWins}–${17-roadWins}, with no ties</small></div><p>${samples>=100?`${qual.toLocaleString()} of ${samples.toLocaleString()} matching simulated seasons qualified.`:samples?`Only ${samples} matching simulations. Too few to quote a stable conditional estimate.`:'No matching seasons in this sample. This does not prove the record is impossible.'}</p><p class="tiny">Your existing simulator picks apply. This conditions on sampled records; it does not enumerate every path or certify clinching.</p><div class="road-bars">${Array.from({length:remaining+1},(_,i)=>bw+i).map(w=>`<button class="road-bin ${w===roadWins?'selected':''}" data-record="${w}" aria-label="Explore ${w} wins"><span>${r?Math.round(100*r.noTieRecords[w]/N)+'%':'—'}</span><i style="height:${r?100*r.noTieRecords[w]/max:1}px"></i><b>${w}–${17-w}</b></button>`).join('')}</div><p class="tiny">Bar heights show how often each no-tie record occurred.</p></section><section class="hub-card"><span class="eyebrow">ONE ILLUSTRATIVE ROUTE</span><h2>Build a ${roadWins}-win scenario.</h2><p>This route assigns Cleveland wins in its most favorable remaining matchups. Other combinations can produce the same record; use the simulator to change any game.</p><div class="road-plan">${plan.map(({g,win})=>`<div class="plan-game ${win?'':'loss'}"><small>WEEK ${g.week} · ${g.h==='CLE'?'HOME':'AWAY'}</small><b>${g.h==='CLE'?'vs.':'at'} ${short(opponent(g))}</b><small>${fmtDate(g)}</small><em>${win?'BROWNS WIN':'BROWNS LOSS'}</em></div>`).join('')}</div><div class="hub-actions" style="margin-top:20px"><button class="hub-primary" id="buildRoad">Apply this route to simulator</button><button data-route="simulator">Edit every game ↗</button></div><p class="tiny">Applying this route replaces picks for Cleveland’s remaining games. Picks for all other teams remain as you set them. Undo is available in the simulator.</p></section></div>`}
function bindRoad(){H('roadWins').onchange=e=>{roadWins=+e.target.value;render()};H('hubView').querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{roadWins=+b.dataset.record;render()});H('buildRoad').onclick=()=>{let next={...picks};roadPlan(roadWins).forEach(({g,win})=>next[g.id]=(g.h==='CLE')===win?1:0);applyPicks(next);route('simulator');toast('Cleveland’s route is locked. Other games remain unchanged.')};}
function cleanLeague(s){return s.toLowerCase().replace(/[^a-z0-9-]/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'dawg-pound'}
function latest(entries,key){let m=new Map();entries.slice().sort((a,b)=>new Date(a.created)-new Date(b.created)||a.id-b.id).forEach(e=>m.set(key(e),e));return [...m.values()]}
function leaders(league,w){let accepted=community.entries.filter(e=>e.kind==='pickem'&&e.league===league&&e.week===+w),users=new Map();accepted.sort((a,b)=>new Date(a.created)-new Date(b.created)||a.id-b.id).forEach(e=>{let u=users.get(e.user)||{user:e.user,picks:{}};Object.assign(u.picks,e.picks);users.set(e.user,u)});return [...users.values()].map(u=>{let correct=0,settled=0;for(let [id,v] of Object.entries(u.picks)){let g=data.games.find(g=>g.id===id);if(g?.done){settled++;if(outcome(g)===v)correct++}}return {...u,correct,settled,total:Object.keys(u.picks).length}}).sort((a,b)=>b.correct-a.correct||b.settled-a.settled||a.user.localeCompare(b.user))}
function renderPickem(){pickDraft.week??=currentWeek();let w=+pickDraft.week,gs=data.games.filter(g=>g.week===w).sort((a,b)=>new Date(a.date)-new Date(b.date)),league=cleanLeague(pickDraft.league),board=leaders(league,w),openPicks=Object.entries(pickDraft.picks).filter(([id])=>gs.some(g=>g.id===id&&!g.timeTBD&&new Date(g.date)>now()));return header('pickem',`<button id="shareLeague">Invite friends ↗</button>`)+notice()+`<div class="hub-grid"><section class="hub-card"><div class="hub-stats-head"><h2>Your weekly card</h2><select id="pickemWeek" aria-label="Pick’em week">${weekOptions(w)}</select></div><div class="hub-form"><label>League name (public; share with friends)<input id="leagueCode" maxlength="40" value="${esc(league)}" placeholder="dawg-pound"></label></div><p class="tiny">Draft picks save on this device. Submit before the chosen games kick off to enter the shared standings.</p>${gs.map(g=>{let closed=g.done||g.timeTBD||new Date(g.date)<=now();return `<div class="pickem-match"><small>${fmtDate(g)} · ${g.done?'FINAL: '+g.a+' '+g.as_+'–'+g.hs+' '+g.h:g.timeTBD?'PICKS OPEN WHEN KICKOFF IS CONFIRMED':closed?'LOCKED — KICKOFF PASSED':'OPEN'}</small><button data-pickem="${g.id}" data-v="0" ${closed?'disabled':''} class="${pickDraft.picks[g.id]===0?'selected':''}">${g.a} · ${short(g.a)}</button><button class="tie ${pickDraft.picks[g.id]===.5?'selected':''}" data-pickem="${g.id}" data-v="0.5" ${closed?'disabled':''}>TIE</button><button data-pickem="${g.id}" data-v="1" ${closed?'disabled':''} class="${pickDraft.picks[g.id]===1?'selected':''}">${g.h} · ${short(g.h)}</button></div>`}).join('')}<div class="pickem-submit"><span>${openPicks.length} open picks ready · GitHub account required</span><button class="hub-primary" id="submitPickem" ${!openPicks.length?'disabled':''}>Review & submit picks ↗</button></div></section><section class="hub-card"><span class="eyebrow">${esc(league.toUpperCase())} / WEEK ${w}</span><h2>Your league leaderboard</h2>${board.length?`<div class="hub-table"><table><thead><tr><th>FAN</th><th>POINTS</th><th>GRADED</th><th>PICKS</th></tr></thead><tbody>${board.map((u,i)=>`<tr><td>${i+1}. ${esc(u.user)}</td><td>${u.correct}</td><td>${u.settled}</td><td>${u.total}</td></tr>`).join('')}</tbody></table></div>`:'<div class="hub-empty">No accepted picks for this league and week yet. Copy an invite, make your picks, and submit the first card.</div>'}${communityState()}<details class="hub-rules"><summary>How scoring and locking work</summary><p>One point for each correctly picked outcome, including a tie only when you explicitly picked a tie. Unpicked games score zero. The backend checks GitHub’s creation timestamp against scheduled kickoff. Later valid submissions can replace that fan’s picks for games that have not kicked off. Accepted entries are frozen; editing or closing the issue does not rewrite the record. Points update when the published results snapshot marks a game final. Equal scores share the same point total; display order is not a tiebreak prize. League codes and entries are public, not private rooms.</p></details></section></div>`}
function bindPickem(){H('pickemWeek').onchange=e=>{pickDraft.week=+e.target.value;save('temu-pickem-draft',pickDraft);render()};H('leagueCode').onchange=e=>{pickDraft.league=cleanLeague(e.target.value);save('temu-pickem-draft',pickDraft);render()};H('hubView').querySelectorAll('[data-pickem]').forEach(b=>b.onclick=()=>{let id=b.dataset.pickem,v=+b.dataset.v;if(pickDraft.picks[id]===v)delete pickDraft.picks[id];else pickDraft.picks[id]=v;save('temu-pickem-draft',pickDraft);render()});H('shareLeague').onclick=()=>{let u=new URL(location.href);u.search='';u.searchParams.set('tab','pickem');u.searchParams.set('league',cleanLeague(pickDraft.league));u.searchParams.set('week',pickDraft.week);copy(u.href,'League invite copied')};H('submitPickem').onclick=()=>{let pp=Object.fromEntries(Object.entries(pickDraft.picks).filter(([id])=>data.games.some(g=>g.id===id&&g.week===+pickDraft.week&&!g.timeTBD&&new Date(g.date)>now()&&!g.done)));if(!Object.keys(pp).length)return toast('All selected games have kicked off. Choose open games.');submit({kind:'pickem',week:+pickDraft.week,league:cleanLeague(pickDraft.league),picks:pp},'Pick’em · '+cleanLeague(pickDraft.league),Object.entries(pp).map(([id,v])=>{let g=data.games.find(g=>g.id===id);return `${g.a} at ${g.h}: ${valueLabel(g,v)}`}).join('\n'))}}
const topics={'next-game':'Next Browns game',quarterback:'Quarterback play',coaching:'Coaching',playoffs:'Playoff confidence'};
function pollEntries(topic,w){return latest(community.entries.filter(e=>e.kind==='confidence'&&e.topic===topic&&e.week===+w),e=>e.user)}
function renderConfidence(){pollState.week??=currentWeek();let w=+pollState.week,votes=pollEntries(pollState.topic,w),avg=votes.length?votes.reduce((s,e)=>s+e.value,0)/votes.length:0,hist=Array.from({length:10},(_,i)=>({value:i+1,count:votes.filter(e=>e.value===i+1).length}));return header('confidence')+notice()+`<div class="hub-grid"><section class="hub-card"><span class="eyebrow">YOUR CONFIDENCE / 1–10</span><h2>How confident are you?</h2><div class="hub-form"><div class="hub-inline"><label>Topic<select id="pollTopic">${Object.entries(topics).map(([k,v])=>`<option value="${k}" ${k===pollState.topic?'selected':''}>${v}</option>`).join('')}</select></label><label>Week<select id="pollWeek">${weekOptions(w,allWeeks().filter(w=>w<=currentWeek()))}</select></label></div><div class="vote-number"><span id="voteValue">${pollState.value}</span><small>/10</small></div><label>Confidence<input id="pollValue" aria-label="Confidence from one to ten" type="range" min="1" max="10" step="1" value="${pollState.value}"></label><div class="vote-scale"><span>1 · NO CONFIDENCE</span><span>10 · ALL IN</span></div><button class="hub-primary" id="submitPoll" ${w!==currentWeek()?'disabled':''}>${w===currentWeek()?'Review & submit confidence vote ↗':'Voting closed for this past week'}</button></div><p class="tiny">Only the current week is open for voting. Past weeks show their recorded results. One displayed vote per GitHub account, topic and week. A newer accepted vote replaces the older vote in the average. A GitHub account is not proof of a unique person.</p></section><section class="hub-card"><span class="eyebrow">WEEK ${w} / ${esc(topics[pollState.topic].toUpperCase())}</span><h2>The Dawg Pound says…</h2><div class="result-large">${votes.length?avg.toFixed(1):'—'}<small>${votes.length} accepted ${votes.length===1?'vote':'votes'} · average confidence out of 10</small></div><div class="poll-bars">${hist.map(x=>`<div class="poll-bar"><span>${x.value}/10</span><span>${x.count}</span><i><span style="width:${votes.length?100*x.count/votes.length:0}%"></span></i></div>`).join('')}</div><h3 style="margin-top:25px">How confidence changes</h3><div class="poll-trend">${allWeeks().filter(x=>x<=currentWeek()).slice(-8).map(w=>{let v=pollEntries(pollState.topic,w),a=v.length?v.reduce((s,x)=>s+x.value,0)/v.length:0;return `<div class="trend-point"><b>${v.length?a.toFixed(1):'—'}</b><i style="height:${a*7}px"></i><span>WK ${w}</span></div>`}).join('')}</div>${communityState()}</section></div>`}
function bindConfidence(){H('pollTopic').onchange=e=>{pollState.topic=e.target.value;render()};H('pollWeek').onchange=e=>{pollState.week=+e.target.value;render()};H('pollValue').oninput=e=>{pollState.value=+e.target.value;H('voteValue').textContent=pollState.value};H('submitPoll').onclick=()=>submit({kind:'confidence',week:+pollState.week,topic:pollState.topic,value:pollState.value},'Confidence vote',`${topics[pollState.topic]} · Week ${pollState.week}\nYour confidence: ${pollState.value}/10`)}
let matchupId='';
function renderMatchup(){let games=cleGames();let g=games.find(g=>g.id===matchupId)||nextGame();matchupId=g.id;let o=opponent(g),c=stats('CLE'),s=stats(o),rows=[['Points scored / game',c.pf,s.pf],['Points allowed / game ↓',c.pa,s.pa],['Point differential / game',c.net,s.net],['Opponent-adjusted rating',data.ratings.CLE,data.ratings[o]]];let advC=roster.statistics?.CLE,advO=roster.statistics?.[o];if(advC&&advO){for(let [label,key] of [['Net passing yards / game','passingYPG'],['Rushing yards / game','rushingYPG'],['Yards per rush','yardsPerRush'],['Sacks generated / game','sacksForPG'],['Sacks allowed / game ↓','sacksAllowedPG'],['Third-down conversion %','thirdDownPct'],['Turnover differential','turnoverDiff']])if(Number.isFinite(advC[key])&&Number.isFinite(advO[key]))rows.push([label,advC[key],advO[key]])}return header('matchup',`<select class="hub-week-picker" id="matchupGame" aria-label="Browns matchup">${games.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>W${x.week}: ${x.h==='CLE'?'vs.':'at'} ${short(opponent(x))}</option>`).join('')}</select>`)+`<div class="hub-grid"><section class="hub-card"><span class="eyebrow">CLEVELAND VS ${esc(meta[o][0].toUpperCase())}</span><h2>${g.done?'What happened.':'Where the matchup stands.'}</h2><p>${fmtDate(g)} · ${g.neutral?'Neutral field':g.h==='CLE'?'Cleveland at home':'Cleveland on the road'}</p><div class="metric-compare"><strong>${logo('CLE')}<small>${record('CLE')}</small></strong><span>2026 SEASON TO DATE</span><strong>${logo(o)}<small>${record(o)}</small></strong></div>${rows.map(([name,a,b])=>`<div class="metric-compare"><strong>${a.toFixed(1)}</strong><span>${name}</span><strong>${b.toFixed(1)}</strong></div>`).join('')}<p class="tiny">Ratings are relative to the league average in point-margin units. Scoring averages use completed games in the published snapshot. For past matchups, these are current season-to-date stats—not pregame historical forecasts. ${advC?'Additional team statistics checked with ESPN '+new Date(advC.checked).toLocaleDateString()+'.':''}</p></section><section class="hub-card"><span class="eyebrow">${g.done?'FINAL RESULT':'MODEL PREVIEW'}</span><h2>${g.done?g.a+' '+g.as_+' — '+g.hs+' '+g.h:Math.round(100*(g.h==='CLE'?g.p:1-g.p))+'% Cleveland win chance'}</h2><p>${g.done?'Result from the published snapshot.':'This is the existing opponent-adjusted game model, with home field and rest. Injuries, quarterback availability and betting lines are not included.'}</p><h3>Last five completed games</h3><div class="hub-row"><span>Cleveland</span><span class="form-chips">${c.form.map(v=>`<b class="form-chip ${v.toLowerCase()}">${v}</b>`).join('')}</span></div><div class="hub-row"><span>${short(o)}</span><span class="form-chips">${s.form.map(v=>`<b class="form-chip ${v.toLowerCase()}">${v}</b>`).join('')}</span></div>${advC&&advO&&Number.isFinite(advC.sacksForPG)&&Number.isFinite(advO.sacksAllowedPG)?`<h3 style="margin-top:25px">The pass-rush matchup</h3><p>Cleveland generates <strong>${advC.sacksForPG.toFixed(1)} sacks per game</strong>. ${short(o)} allows <strong>${advO.sacksAllowedPG.toFixed(1)}</strong>. At the other end, Cleveland allows ${advC.sacksAllowedPG?.toFixed(1)??'—'} while ${short(o)} generates ${advO.sacksForPG?.toFixed(1)??'—'}. These are season averages, not a predicted sack total.</p>`:''}<h3 style="margin-top:25px">The scoring paths</h3><p><strong>When Cleveland has the ball:</strong> its ${c.pf.toFixed(1)} points per game meets an opponent allowing ${s.pa.toFixed(1)}. This is a scoring comparison, not a possession-level projection.</p><p><strong>When ${short(o)} has the ball:</strong> ${s.pf.toFixed(1)} scored per game meets Cleveland’s ${c.pa.toFixed(1)} allowed. Recent W/L form appears above, oldest to newest.</p><div class="hub-actions"><button class="hub-primary" id="makeMatchupCard">Make a matchup card ↗</button><button data-route="simulator">Open playoff simulator</button></div></section></div>`}
function bindMatchup(){H('matchupGame').onchange=e=>{matchupId=e.target.value;render()};H('makeMatchupCard').onclick=()=>{graphicState.type='matchup';graphicState.game=matchupId;route('graphics')}}
function receiptResult(r){let g=data.games.find(g=>g.id===r.game);if(!g)return {text:'Game unavailable',cls:'pending'};if(!g.done)return {text:'PENDING · Grades after the published game result is final',cls:'pending'};return outcome(g)===r.winner?{text:'CORRECT · '+g.a+' '+g.as_+'–'+g.hs+' '+g.h,cls:''}:{text:'MISSED · '+g.a+' '+g.as_+'–'+g.hs+' '+g.h,cls:'wrong'}}
function renderReceipts(){let gs=cleGames().filter(g=>!g.done&&!g.timeTBD&&new Date(g.date)>now());if(!gs.some(g=>g.id===receiptDraft.game))receiptDraft.game=gs[0]?.id||'';let game=gs.find(g=>g.id===receiptDraft.game),pub=community.entries.filter(e=>e.kind==='receipt').slice().sort((a,b)=>new Date(b.created)-new Date(a.created));return header('receipts')+notice()+`<div class="hub-grid"><section class="hub-card"><span class="eyebrow">PUT IT ON RECORD</span><h2>What’s your call?</h2><div class="hub-form"><label>Browns game<select id="receiptGame" ${!gs.length?'disabled':''}>${gs.map(g=>`<option value="${g.id}" ${g.id===receiptDraft.game?'selected':''}>W${g.week}: ${g.a} at ${g.h}</option>`).join('')}</select></label><label>Your predicted result<select id="receiptWinner">${game?`<option value="0" ${receiptDraft.winner===0?'selected':''}>${short(game.a)} win</option><option value="1" ${receiptDraft.winner===1?'selected':''}>${short(game.h)} win</option><option value="0.5" ${receiptDraft.winner===.5?'selected':''}>Tie</option>`:''}</select></label><label>Your take (optional; only the winner is automatically graded)<textarea id="receiptNote" maxlength="240" placeholder="Here’s why I’m calling it…">${esc(receiptDraft.note)}</textarea></label><div class="hub-actions"><button id="publishReceipt" class="hub-primary" ${!game?'disabled':''}>Review & timestamp publicly ↗</button><button id="saveReceipt" ${!game?'disabled':''}>Save a personal draft</button></div></div><p class="tiny">Public receipts use GitHub’s submission timestamp and freeze before kickoff. Personal drafts stay on this device and are not independently verified timestamps.</p><h3 style="margin-top:25px">Personal drafts</h3>${localReceipts.length?localReceipts.slice().reverse().map((r,i)=>{let g=data.games.find(g=>g.id===r.game),s=receiptResult(r);return `<article class="receipt-card draft-receipt"><div class="receipt-top"><span>LOCAL DRAFT · NOT VERIFIED</span><span>${esc(new Date(r.created).toLocaleDateString())}</span></div><h3>${g?esc(valueLabel(g,r.winner)):'Game unavailable'}</h3><p>${esc(r.note)}</p><div class="receipt-result ${s.cls}">${esc(s.text)}</div><button data-delete-local="${localReceipts.length-1-i}" class="quiet">Delete draft</button></article>`}).join(''):'<p class="hub-empty">No personal drafts saved.</p>'}</section><section class="hub-card"><span class="eyebrow">THE PUBLIC RECEIPT BOOK</span><h2>Keep that same energy.</h2>${pub.length?pub.map(r=>{let g=data.games.find(g=>g.id===r.game),s=receiptResult(r);return `<article class="receipt-card"><div class="receipt-top"><span>@${esc(r.user)}</span><span>${esc(new Date(r.created).toLocaleString())}</span></div><h3>${g?esc(valueLabel(g,r.winner)):'Game unavailable'}</h3><p>${esc(r.note)}</p><a href="${esc(r.url)}" target="_blank" rel="noopener">View original submission #${r.id} ↗</a><div class="receipt-result ${s.cls}">${esc(s.text)}</div></article>`}).join(''):'<div class="hub-empty">No public receipts yet. Make your first call before kickoff.</div>'}${communityState()}</section></div>`}
function bindReceipts(){const stash=()=>save('temu-receipt-draft',receiptDraft);H('receiptGame').onchange=e=>{receiptDraft.game=e.target.value;stash();render()};H('receiptWinner').onchange=e=>{receiptDraft.winner=+e.target.value;stash()};H('receiptNote').oninput=e=>{receiptDraft.note=e.target.value;stash()};H('saveReceipt').onclick=()=>{localReceipts.push({...receiptDraft,created:new Date().toISOString()});save('temu-local-receipts',localReceipts);render();toast('Personal draft saved; timestamp is not independently verified')};H('publishReceipt').onclick=()=>{let g=data.games.find(g=>g.id===receiptDraft.game);if(!g||new Date(g.date)<=now())return toast('This game has kicked off. Choose a later game.');submit({kind:'receipt',week:g.week,game:g.id,winner:receiptDraft.winner,note:receiptDraft.note},'Browns receipt',`${valueLabel(g,receiptDraft.winner)}\n${g.a} at ${g.h} · ${fmtDate(g)}\n${receiptDraft.note}`)};H('hubView').querySelectorAll('[data-delete-local]').forEach(b=>b.onclick=()=>{localReceipts.splice(+b.dataset.deleteLocal,1);save('temu-local-receipts',localReceipts);render()})}
const awardNames={mvp:'Most Valuable Brown',play:'Play of the Season',surprise:'Biggest Surprise',unsung:'Unsung Hero'};
function awardVotes(category,period,w){return latest(community.entries.filter(e=>e.kind==='award'&&e.category===category&&(e.period||'season')===period&&(period==='season'||e.week===+w)),e=>e.user)}
function renderAwards(){awardState.week??=Math.max(...cleGames().filter(g=>g.done).map(g=>g.week),1);let votes=awardVotes(awardState.category,awardState.period,awardState.week),tally=new Map();votes.forEach(e=>{let key=e.nominee.trim().toLowerCase();let v=tally.get(key)||{name:e.nominee,count:0};v.count++;tally.set(key,v)});let sorted=[...tally.values()].sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name)),weeks=allWeeks().filter(w=>w<=currentWeek());return header('awards')+notice()+`<div class="hub-grid"><section class="hub-card"><span class="eyebrow">YOUR BALLOT</span><h2>Who deserves the flowers?</h2><div class="hub-form"><label>Award<select id="awardCategory">${Object.entries(awardNames).map(([k,v])=>`<option value="${k}" ${awardState.category===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="hub-inline"><label>Ballot<select id="awardPeriod"><option value="season" ${awardState.period==='season'?'selected':''}>Season award race</option><option value="weekly" ${awardState.period==='weekly'?'selected':''}>Weekly award</option></select></label>${awardState.period==='weekly'?`<label>Week<select id="awardWeek">${weekOptions(awardState.week,weeks)}</select></label>`:''}</div><label>${awardState.category==='play'?'Describe the play':'Your nominee'}<input id="awardNominee" list="brownsRoster" maxlength="90" value="${esc(awardState.nominee)}" placeholder="${awardState.category==='play'?'Week, opponent and play description':'Start typing a player’s name'}"></label><datalist id="brownsRoster">${roster.players.map(p=>`<option value="${esc(p.name)}">${esc(p.position)}</option>`).join('')}</datalist><button id="submitAward" class="hub-primary">Review & submit award vote ↗</button></div><p class="tiny">Season races show each account’s latest choice per award. Weekly awards count the latest vote per account, week and award. Nominees and play descriptions are fan submissions; they are not staff endorsements.</p>${roster.updated?`<p class="tiny">Roster suggestions: ESPN · ${new Date(roster.updated).toLocaleDateString()}. You can nominate a player who isn’t in the suggestions.</p>`:''}</section><section class="hub-card"><span class="eyebrow">${awardState.period==='season'?'SEASON RACE':'WEEK '+awardState.week}</span><h2>${awardNames[awardState.category]}</h2><p class="award-count">${votes.length} accepted ${votes.length===1?'vote':'votes'}</p>${sorted.length?`<div class="poll-bars">${sorted.map(v=>`<div class="poll-bar"><span>${esc(v.name)}</span><span>${v.count} · ${Math.round(v.count/votes.length*100)}%</span><i><span style="width:${100*v.count/votes.length}%"></span></i></div>`).join('')}</div>`:'<div class="hub-empty">No votes in this award race yet. Cast the first ballot.</div>'}${communityState()}<p class="tiny">Results update after fan submissions are accepted and published.</p></section></div>`}
function bindAwards(){H('awardCategory').onchange=e=>{awardState.category=e.target.value;awardState.nominee='';render()};H('awardPeriod').onchange=e=>{awardState.period=e.target.value;render()};if(H('awardWeek'))H('awardWeek').onchange=e=>{awardState.week=+e.target.value;render()};H('awardNominee').oninput=e=>awardState.nominee=e.target.value;H('submitAward').onclick=()=>{let nominee=awardState.nominee.trim();if(!nominee)return toast('Enter a nominee or describe the play first.');submit({kind:'award',week:awardState.period==='season'?currentWeek():+awardState.week,period:awardState.period,category:awardState.category,nominee},'Dawg Pound award vote',`${awardNames[awardState.category]}\n${awardState.period==='season'?'Season race':'Week '+awardState.week}\nYour nominee: ${nominee}`)}}
function graphicGames(){return graphicState.type==='victory'?cleGames().filter(g=>g.done&&cleWin(g)):cleGames()}
function graphicGame(){let gs=graphicGames();return gs.find(g=>g.id===graphicState.game)||(graphicState.type==='victory'?gs.at(-1):nextGame())||gs[0]}
function renderGraphics(){let gs=graphicGames(),g=graphicGame();if(g)graphicState.game=g.id;let disabled=graphicState.type!=='prediction';return header('graphics')+`<div class="hub-grid"><section class="hub-card"><span class="eyebrow">MAKE IT YOURS</span><h2>Built for the group chat.</h2><div class="hub-form"><label>Graphic type<select id="graphicType"><option value="prediction" ${graphicState.type==='prediction'?'selected':''}>Score prediction</option><option value="matchup" ${graphicState.type==='matchup'?'selected':''}>Matchup card</option><option value="victory" ${graphicState.type==='victory'?'selected':''}>Verified victory card</option><option value="playoffs" ${graphicState.type==='playoffs'?'selected':''}>Playoff scenario</option></select></label>${graphicState.type!=='playoffs'?`<label>Game<select id="graphicGame">${gs.map(x=>`<option value="${x.id}" ${g?.id===x.id?'selected':''}>W${x.week}: ${x.a} at ${x.h}</option>`).join('')}</select></label>`:''}${graphicState.type==='prediction'&&g?`<div class="hub-inline"><label>${short(g.a)} score<input id="graphicAway" type="number" min="0" max="99" value="${graphicState.away}"></label><label>${short(g.h)} score<input id="graphicHome" type="number" min="0" max="99" value="${graphicState.home}"></label></div>`:''}<label>Custom caption (up to 55 characters)<input id="graphicCaption" maxlength="55" value="${esc(graphicState.caption)}"></label></div><div class="graphic-actions"><button class="hub-primary" id="downloadGraphic" ${!g&&graphicState.type!=='playoffs'?'disabled':''}>Download PNG ↓</button><button id="shareGraphic" ${!g&&graphicState.type!=='playoffs'?'disabled':''}>Share image ↗</button></div><p class="tiny">1200 × 1200 pixels. Prediction cards are labeled fan predictions. Victory cards use completed Cleveland wins only. Playoff cards use your current simulator picks and are labeled model estimates.</p><div class="hub-actions"><button data-route="simulator">Change playoff scenario</button><button data-route="matchup">See matchup data</button></div></section><section class="hub-card"><canvas class="graphic-preview" id="graphicCanvas" width="1200" height="1200" aria-label="Preview of your downloadable Browns graphic"></canvas></section></div>`}
function drawGraphic(){let canvas=H('graphicCanvas');if(!canvas)return;let c=canvas.getContext('2d'),g=graphicGame();c.clearRect(0,0,1200,1200);let bg=c.createLinearGradient(0,0,1200,1200);bg.addColorStop(0,'#2b1e18');bg.addColorStop(.5,'#111f2a');bg.addColorStop(1,'#0c151d');c.fillStyle=bg;c.fillRect(0,0,1200,1200);c.strokeStyle='#ffffff09';c.lineWidth=2;for(let x=100;x<1200;x+=100){c.beginPath();c.moveTo(x,0);c.lineTo(x,1200);c.stroke()}c.fillStyle='#f59550';c.fillRect(70,68,14,78);c.textAlign='left';c.font='700 34px "DM Sans",sans-serif';c.fillStyle='#fff2e4';c.fillText('TEMU',106,103);c.font='500 18px "DM Sans",sans-serif';c.fillStyle='#b9a797';c.fillText('PLAYOFF PREDICTOR',106,137);c.textAlign='right';c.font='600 20px "DM Sans",sans-serif';c.fillStyle='#db9e6a';c.fillText('DAWG POUND / 2026',1120,110);c.textAlign='center';const type=graphicState.type;
 c.fillStyle='#c7b3a0';c.font='600 23px "DM Sans",sans-serif';c.fillText({prediction:'FAN SCORE PREDICTION',matchup:'GAME DAY / MATCHUP',victory:'FINAL SCORE / CLEVELAND WINS',playoffs:'YOUR PLAYOFF SCENARIO / MODEL ESTIMATE'}[type],600,245);
 if(type==='playoffs'){c.fillStyle='#ffb07c';c.font='700 110px "Barlow Condensed",sans-serif';c.fillText('CLEVELAND BROWNS',600,390);c.fillStyle='#d2f48b';c.font='700 230px "Barlow Condensed",sans-serif';c.fillText(getBrowns()?percent(getBrowns().play):'—',600,665);c.font='600 42px "Barlow Condensed",sans-serif';c.fillStyle='#d5e0dc';c.fillText('CHANCE TO MAKE THE PLAYOFFS',600,745);c.font='500 24px "DM Sans",sans-serif';c.fillStyle='#9fb2bd';c.fillText(Object.keys(picks).length+' results picked · 10,000 simulations',600,815)}else if(g){let a=g.a,h=g.h;function badge(t,x){c.fillStyle=meta[t][1];c.beginPath();c.roundRect(x-105,330,210,150,25);c.fill();c.fillStyle='#fff';c.font='700 72px "Barlow Condensed",sans-serif';c.fillText(t,x,432);c.fillStyle='#f3e8df';c.font='600 52px "Barlow Condensed",sans-serif';c.fillText(short(t).toUpperCase(),x,555)}badge(a,325);badge(h,875);c.fillStyle='#7e8589';c.font='600 30px "DM Sans",sans-serif';c.fillText(type==='matchup'?'AT':'—',600,690);if(type==='prediction'||type==='victory'){c.fillStyle='#ffc08d';c.font='700 155px "Barlow Condensed",sans-serif';c.fillText(String(type==='victory'?g.as_:graphicState.away),325,745);c.fillText(String(type==='victory'?g.hs:graphicState.home),875,745)}else{c.fillStyle='#d1e0d7';c.font='600 110px "Barlow Condensed",sans-serif';c.fillText(record(a),325,735);c.fillText(record(h),875,735)}c.font='500 24px "DM Sans",sans-serif';c.fillStyle='#91a7b5';c.fillText('WEEK '+g.week+' · '+(g.timeTBD?'KICKOFF TBD':new Date(g.date).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}).toUpperCase()),600,830)}else{c.fillStyle='#fff';c.font='500 35px "DM Sans",sans-serif';c.fillText('No eligible completed Cleveland wins.',600,600)}
 let caption=graphicState.caption.trim().toUpperCase();let size=53;do{c.font=`700 ${size--}px "Barlow Condensed",sans-serif`}while(c.measureText(caption).width>1030&&size>20);c.fillStyle='#f5a065';c.fillText(caption,600,985);c.strokeStyle='#ffffff25';c.beginPath();c.moveTo(70,1050);c.lineTo(1130,1050);c.stroke();c.font='500 19px "DM Sans",sans-serif';c.fillStyle='#8095a4';c.fillText('seanpullins.github.io/playoff-lab',600,1100);c.font='400 14px "DM Sans",sans-serif';c.fillText(type==='playoffs'?'Exploratory model · Approximate tiebreakers · Not a clinching declaration':'Independent fan graphic · Not affiliated with the NFL',600,1140)}
function graphicBlob(){return new Promise(resolve=>H('graphicCanvas').toBlob(resolve,'image/png'))}
function bindGraphics(){H('graphicType').onchange=e=>{graphicState.type=e.target.value;graphicState.game='';render()};if(H('graphicGame'))H('graphicGame').onchange=e=>{graphicState.game=e.target.value;drawGraphic()};for(let id of ['graphicAway','graphicHome'])if(H(id))H(id).oninput=e=>{let v=Math.max(0,Math.min(99,Math.round(+e.target.value||0)));graphicState[id==='graphicAway'?'away':'home']=v;drawGraphic()};H('graphicCaption').oninput=e=>{graphicState.caption=e.target.value;drawGraphic()};H('downloadGraphic').onclick=async()=>{let blob=await graphicBlob();if(!blob)return;let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='temu-browns-'+graphicState.type+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};H('shareGraphic').onclick=async()=>{let blob=await graphicBlob();if(!blob)return;let file=new File([blob],'temu-browns-'+graphicState.type+'.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'TEMU PLAYOFF PREDICTOR'});else{H('downloadGraphic').click();toast('Image downloaded. Share it from your photos or files.')}}catch(e){if(e.name!=='AbortError')toast('Sharing unavailable. Use Download PNG.')}};drawGraphic();document.fonts.ready.then(drawGraphic)}
function submit(payload,label,summary){currentDraft={version:1,...payload};let dialog=H('submissionDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='submissionDialog';dialog.innerHTML='<div class="dialog-head"><h2 id="submissionTitle"></h2><button id="closeSubmission" aria-label="Close submission review">×</button></div><div class="dialog-body"><p>You’re about to open GitHub with this entry prefilled. A free GitHub account is required. After you click <strong>Create issue</strong> there, your username and entry will be public. No entry is posted automatically.</p><div class="submission-summary" id="submissionSummary"></div><p>Accepted entries are frozen from the original opened submission. Editing or closing an issue does not change its accepted record. If you edit an entry before it is processed, it may be skipped; submit a new entry instead. Picks and receipts must reach GitHub before scheduled kickoff.</p><a class="submission-link" id="submissionLink" target="_blank" rel="noopener">Continue to GitHub ↗</a><p class="muted">Results appear after validation and a site update, usually within a few minutes. Invalid or late entries will not appear.</p></div>';document.body.append(dialog);H('closeSubmission').onclick=()=>dialog.close()}H('submissionTitle').textContent=label;H('submissionSummary').textContent=summary;let u=new URL('https://github.com/SeanPullins/playoff-lab/issues/new');u.searchParams.set('title','TEMU | '+label);u.searchParams.set('body','Submitted from TEMU PLAYOFF PREDICTOR. This entry is public.\n\n```json\n'+JSON.stringify(currentDraft,null,2)+'\n```\n\nThe original opened submission is used; edits do not rewrite accepted records.');H('submissionLink').href=u.href;dialog.showModal()}
async function copy(value,message){try{await navigator.clipboard.writeText(value);toast(message)}catch{toast('Copy is unavailable in this browser. Use your browser’s share menu.')}}
async function loadCommunity(){try{let r=await fetch('community.json?v='+now(),{cache:'no-store'});if(!r.ok)throw Error();let d=await r.json();if(!Array.isArray(d.entries))throw Error();community=d;communityError=false}catch{communityError=true}}
let urlParams=new URLSearchParams(location.search);if(urlParams.has('league'))pickDraft.league=cleanLeague(urlParams.get('league'));if(+urlParams.get('week')>=1&&+urlParams.get('week')<=18)pickDraft.week=+urlParams.get('week');
document.querySelectorAll('[data-hub]').forEach(b=>b.onclick=()=>route(b.dataset.hub));let callout=document.createElement('div');callout.className='hub-callout';callout.innerHTML='<span><strong>The rest of the Browns season, in one place.</strong> Scoreboard, pick’em leagues, fan votes, receipts and shareable graphics.</span><button id="openBrownsHQ">Explore Browns HQ ↗</button>';H('simulatorView').prepend(callout);H('openBrownsHQ').onclick=()=>route('hq');H('exploreNav').onclick=()=>{route('simulator');window.scrollTo({top:0,behavior:'smooth'})};
document.addEventListener('lab:dataerror',render);
document.addEventListener('lab:update',()=>{if(view!=='simulator'&&['hq','road','matchup','graphics'].includes(view))render();else if(view!=='simulator'&&H('hubView').querySelector('.hub-loader'))render()});
Promise.all([loadCommunity(),fetch('hub-data.json').then(r=>r.ok?r.json():{players:[]}).then(d=>roster=d).catch(()=>{})]).then(()=>{if(view!=='simulator')render()});
setInterval(()=>{if(view==='hq'&&autoLive&&!document.hidden)refreshScores()},60000);window.addEventListener('popstate',()=>route(new URLSearchParams(location.search).get('tab')||(new URLSearchParams(location.search).has('p')?'simulator':'hq'),false));route(urlParams.get('tab')||(urlParams.has('p')?'simulator':'hq'),false);
})();
